#include <Need.hpp>

std::complex<double> lnrat(double x, double y) {
  using namespace constants_mod;

  // define Heaviside theta function (=1 for x>0) and (0 for x < 0)
  auto htheta = [&](double x) -> double {
    return half + half*sign(x);
  };

